python - <<'PY'
from boltons.iterutils import research, split, split_iter

for make_source in (lambda: [1, None, 2], lambda: (1, None, 2),
                    lambda: iter([1, None, 2]), lambda: 'abc',
                    lambda: range(3), lambda: [], lambda: {}):
    for func in (split, lambda *a, **kw: list(split_iter(*a, **kw))):
        src = make_source()
        expected = list(make_source())
        result = func(src, maxsplit=0)
        assert result == [expected], (src, result)
        assert result[0] is not src

shared = {'leaf': 42}
root = {'a': shared, 'b': shared}
query = lambda p, k, v: k == 'leaf'
assert research(root, query) == [(('a', 'leaf'), 42)]
assert research(root, query, cache=False) == [
    (('a', 'leaf'), 42), (('b', 'leaf'), 42)]
for circular in ([], {}):
    if isinstance(circular, list):
        circular.append(circular)
    else:
        circular['self'] = circular
    research(circular, cache=True)
    try:
        research(circular, cache=False)
    except RecursionError:
        pass
    else:
        raise AssertionError('expected circular reference detection')
print('Targeted edge-case checks passed')
PY
